import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { basename, dirname, join, relative } from 'node:path';
import {
  type Page,
  type Outline,
  type Config,
  type Issue,
  canonical,
  entriesOf,
  yamlText,
  readYaml,
  issue,
  slug,
  allInline,
  markdownBlocks,
  walk,
} from './model';
import { outlineText } from './outline';

export const MARK =
  '<!-- Generated by doccheck gen from page front matter, outline.yaml and overview.yaml. Do not edit. -->';
const names = [
  'Core: read before changing any code',
  "Supporting: read before changing this area's code",
  'Edge: details, known bugs and rare paths',
];
const ranks = ['core', 'supporting', 'edge'];
const pretty = (s: string) => s.charAt(0).toUpperCase() + s.slice(1).replace(/-/g, ' ');
export function expectedGenerated(
  docs: string,
  pages: Page[],
  o: Outline,
  c: Config,
  issues: Issue[],
): Map<string, string> {
  const out = new Map<string, string>();
  const by = new Map(pages.map(p => [canonical(p.rel), p]));
  const title = (full: string) =>
    /^domain\/[^/]+\/index\.md$/.test(full)
      ? pretty(full.split('/')[1])
      : (by.get(canonical(full))?.fm.title ?? pretty(basename(full).replace(/\.dh\.md$|\.md$/, '')));
  const link = (full: string, from = '', rank?: string) => {
    const p = by.get(canonical(full));
    const actual = p?.rel ?? full;
    const target = relative(from || '.', actual)
      .split('\\')
      .join('/');
    const flags = [p?.fm.stub ? 'stub' : '', p?.doc.source.includes('**Watch out:**') ? 'watch out' : '', rank ?? '']
      .filter(Boolean)
      .map(s => ` (${s})`)
      .join('');
    const context = full.match(/^domain\/([^/]+)\/index\.md$/)?.[1];
    const description = context
      ? (o.contexts.find(c => c.context === context)?.learns ?? '')
      : (p?.fm.description ?? entriesOf(o).find(e => canonical(e.full) === canonical(full))?.learns ?? '');
    return `- [${title(full)}](${target})${flags}: ${description}`;
  };
  const map = (path: string, title: string, body: string[]) =>
    out.set(join(docs, path), [`# ${title}`, '', MARK, '', ...body].join('\n').trimEnd() + '\n');
  for (const ctx of o.contexts) {
    const dir = `domain/${ctx.context}/`;
    const ovFile = join(docs, dir, 'overview.yaml');
    let intro = '';
    try {
      const ov = readYaml(ovFile);
      if (
        !ov ||
        typeof ov !== 'object' ||
        Array.isArray(ov) ||
        Object.keys(ov).some(k => k !== 'intro') ||
        typeof ov.intro !== 'string' ||
        !ov.intro.trim()
      )
        throw new Error('overview.yaml needs only a nonempty intro');
      intro = ov.intro.trim();
      if (/\]\(|<https?:|https?:\/\//.test(intro))
        issue(issues, ovFile, 'page list in a page', 'overview intro contains a link');
    } catch (e) {
      issue(issues, ovFile, 'doc shape', `context needs overview.yaml with intro: ${(e as Error).message}`);
    }
    const name = pretty(ctx.context);
    let namespaces: string[] = [];
    const ul = join(docs, dir, 'UL.yaml');
    if (existsSync(ul)) {
      try {
        const ns = readYaml(ul)?.namespace;
        if (typeof ns === 'string') namespaces = [ns];
      } catch (e) {
        issue(issues, ul, 'doc shape', `cannot read context namespace: ${(e as Error).message}`);
      }
    }
    const idx = ctx.pages.find(e => e.full === dir + 'index.md');
    const b = [MARK, '', intro, '', '## Pages, in reading order', ''];
    ranks.forEach((r, i) => {
      const es = ctx.pages.filter(e => e.full !== dir + 'index.md' && e.rank === r);
      if (es.length) b.push(`### ${names[i]}`, '', ...es.map(e => link(e.full, dir)), '');
    });
    out.set(join(docs, dir, 'index.md'), `# ${name}\n\n${b.join('\n').trimEnd()}\n`);
  }
  const top: string[] = [];
  if (o.readingPath.length)
    top.push(
      '## Reading path',
      '',
      ...o.readingPath.map((p, i) => `${i + 1}. [${title(p)}](${by.get(canonical(p))?.rel ?? p})`),
      '',
    );
  if (o.repo.length) top.push('## Across contexts', '', ...o.repo.map(e => link(e.full, '', e.rank)), '');
  if (o.contexts.length)
    top.push(
      '## Domain',
      '',
      ...o.contexts.map(
        ctx => `- [${title(`domain/${ctx.context}/index.md`)}](domain/${ctx.context}/index.md): ${ctx.learns ?? ''}`,
      ),
      '',
    );
  top.push('## Areas', '');
  for (const [dir, title] of [
    ['domain', 'Domain'],
    ['guides', 'Guides'],
    ['standards', 'Engineering standards'],
  ])
    if (existsSync(join(docs, dir))) top.push(`- [${title}](${dir}/README.md)`);
  const adrFolders = [...new Set(pages.filter(p => p.adr).map(p => dirname(p.rel)))].sort();
  if (adrFolders.length) top.push('', '## Decisions', '', ...adrFolders.map(dir => `- [${dir}](${dir}/README.md)`));
  map('README.md', 'Documentation', top);
  if (existsSync(join(docs, 'domain')))
    map(
      'domain/README.md',
      'Domain',
      o.contexts.flatMap(ctx => [
        link(`domain/${ctx.context}/index.md`, 'domain'),
        ...ctx.pages.filter(e => !e.full.endsWith('/index.md')).map(e => '  ' + link(e.full, 'domain', e.rank)),
      ]),
    );
  if (existsSync(join(docs, 'guides')))
    map(
      'guides/README.md',
      'Guides',
      o.guides.map(e => link(e.full, 'guides', e.rank)),
    );
  for (const dir of adrFolders) {
    const adrs = pages.filter(p => p.adr && dirname(p.rel) === dir).sort((a, b) => a.rel.localeCompare(b.rel));
    const lines = adrs.map(p => {
      const newer = adrs.filter(a => (a.fm.supersedes ?? []).some((s: string) => join(dirname(a.rel), s) === p.rel));
      return (
        link(p.rel, dir) +
        (newer.length ? `; superseded by ${newer.map(a => `[${a.fm.title}](${basename(a.rel)})`).join(', ')}` : '')
      );
    });
    map(dir + '/README.md', 'Decisions', lines);
  }
  // References between standards come from links, namespace metadata and explicit UL see entries.
  const standards = pages.filter(p => p.rel.startsWith('standards/') && !p.adr && !p.translated);
  const groups = [...new Set(standards.map(p => p.rel.split('/')[1]))].sort();
  const nsToGroup = new Map<string, string>();
  const ulData = new Map<string, any>();
  for (const group of groups) {
    const f = join(docs, 'standards', group, 'UL.yaml');
    if (!existsSync(f)) continue;
    try {
      const data = readYaml(f);
      ulData.set(group, data);
      if (typeof data?.namespace === 'string') nsToGroup.set(data.namespace, group);
    } catch (e) {
      issue(issues, f, 'generated files', `cannot read standard metadata: ${(e as Error).message}`);
    }
  }
  const edges = new Map<string, { a: string; b: string; why: string }>();
  const edge = (a: string, b: string, why: string) => {
    if (a !== b && groups.includes(b)) edges.set(`${a}:${b}:${why}`, { a, b, why });
  };
  for (const p of standards) {
    const a = p.rel.split('/')[1];
    for (const x of allInline(markdownBlocks(p.doc)))
      if (x.t === 'link' && x.href) {
        const dest = join(dirname(p.rel), x.href)
          .replace(/\\/g, '/')
          .match(/^standards\/([^/]+)\//);
        if (dest) edge(a, dest[1], `link in ${p.rel}`);
      }
    for (const ns of p.fm.namespaces ?? []) {
      const b = nsToGroup.get(ns);
      if (b) edge(a, b, `namespaces in ${p.rel}`);
    }
  }
  for (const [a, d] of ulData)
    for (const v of Object.values<any>(d.language ?? {}))
      for (const s of v.see ?? []) {
        const b = nsToGroup.get(String(s).split('#')[0]);
        if (b) edge(a, b, `see in standards/${a}/UL.yaml`);
      }
  const standardLines = groups.flatMap(group => {
    const index = standards.find(p => p.rel === `standards/${group}/index.md`);
    return [
      ...(index ? [link(index.rel, 'standards')] : [`- ${pretty(group)}`]),
      ...standards.filter(p => p.rel.split('/')[1] === group && p !== index).map(p => '  ' + link(p.rel, 'standards')),
    ];
  });
  if (edges.size) {
    standardLines.push('', '## How standards link up', '', '| From | To | Through |', '| --- | --- | --- |');
    const es = [...edges.values()].sort((x, y) => `${x.a}:${x.b}:${x.why}`.localeCompare(`${y.a}:${y.b}:${y.why}`));
    for (const e of es) standardLines.push(`| ${e.a} | ${e.b} | ${e.why} |`);
    const ids = new Map(groups.map((g, i) => [g, `s${i}`]));
    standardLines.push(
      '',
      '```mermaid',
      'flowchart LR',
      ...groups.map(g => `  ${ids.get(g)}[${JSON.stringify(g)}]`),
      ...[...new Set(es.map(e => `  ${ids.get(e.a)} --> ${ids.get(e.b)}`))],
      '```',
    );
  }
  if (existsSync(join(docs, 'standards'))) map('standards/README.md', 'Engineering standards', standardLines);
  if (c.pageOrder === 'A') out.set(join(docs, 'outline.yaml'), outlineText(o));
  return out;
}
export function generate(docs: string, pages: Page[], o: Outline, c: Config, check: boolean, issues: Issue[]): number {
  const out = expectedGenerated(docs, pages, o, c, issues);
  let n = 0;
  for (const f of walk(docs).filter(f => basename(f) === 'README.md' && !relative(docs, f).startsWith('i18n/')))
    if (!out.has(f))
      issue(issues, f, 'generated files', 'unexpected README map; context folders have only their generated index.md');
  if (issues.some(i => i.level === 'error')) return 0;
  for (const [file, text] of out) {
    if (existsSync(file) && readFileSync(file, 'utf8') === text) continue;
    if (check) issue(issues, file, 'generated files', 'missing or differs from doccheck gen; run doccheck gen');
    else {
      mkdirSync(dirname(file), { recursive: true });
      writeFileSync(file, text);
      n++;
    }
  }
  return n;
}
